/* Shared local studio: immutable retries, revision checks and durable drafts. */
(()=>{'use strict';
 const S=window.AtelierStudio={objects:[],boards:[],food:[],ready:false};
 S.node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
 S.button=(text,fn,cls='')=>{const b=S.node('button',cls,text);b.type='button';b.onclick=fn;return b};
 S.id=()=>crypto.randomUUID();
 S.error=e=>{if(typeof showUiError==='function')showUiError(e,'L’Atelier');else alert(e.message||String(e))};
 S.transport=window.AtelierStudioTransport||((...args)=>api(...args));
 S.command=async(action,payload,id=S.id())=>S.transport('/api/studio/actions',{method:'POST',body:JSON.stringify({operation_id:id,action,payload})});
 S.refresh=async()=>{const data=await S.transport('/api/studio/snapshot');Object.assign(S,data,{ready:true});window.dispatchEvent(new Event('studio-updated'));return data};
 S.of=kind=>S.objects.filter(o=>o.kind===kind&&!o.archived);
 S.save=async(object)=>{const operation=S.id();const result=await S.command('save',object,operation);const i=S.objects.findIndex(o=>o.id===result.id);if(i>=0)S.objects[i]=result;else S.objects.push(result);return result};
 S.create=(kind,data)=>S.save({id:S.id(),kind,revision:0,data});
 S.archive=async o=>{if(!confirm('Archiver « '+(o.data.title||'cette page')+' » ? Les données sont conservées.'))return false;await S.save({...o,archived:true});window.dispatchEvent(new Event('studio-updated'));return true};
 S.draft=(id,data)=>{try{localStorage.setItem('atelier-studio-draft:'+id,JSON.stringify(data));return true}catch(e){S.error(new Error('Brouillon local plein : enregistre avant de continuer.'));return false}};
 S.readDraft=id=>{try{return JSON.parse(localStorage.getItem('atelier-studio-draft:'+id)||'null')}catch{return null}};
 S.clearDraft=id=>localStorage.removeItem('atelier-studio-draft:'+id);
 S.file=async file=>{if(file.size>4200000)throw Error('Photo limitée à 4 Mo.');const data=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file)});return S.command('asset',{base64:data.split(',')[1]})};
 S.pick=accept=>new Promise(resolve=>{const f=S.node('input');f.type='file';f.accept=accept;f.onchange=()=>resolve(f.files?.[0]||null);f.addEventListener('cancel',()=>resolve(null));f.click()});
 S.menu=(event,choices)=>{event?.preventDefault();event?.stopPropagation();document.querySelector('.studio-menu')?.dispatchEvent(new Event('studio-close'));const menu=S.node('div','studio-menu');menu.setAttribute('role','menu');const close=()=>{menu.remove();document.removeEventListener('pointerdown',outside,true);document.removeEventListener('keydown',key,true)};const outside=e=>{if(!menu.contains(e.target))close()};const key=e=>{if(e.key==='Escape'){close();return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const a=[...menu.querySelectorAll('button')],i=a.indexOf(document.activeElement);a[(i+(e.key==='ArrowDown'?1:-1)+a.length)%a.length]?.focus()}};menu.addEventListener('studio-close',close);for(const [label,fn] of choices){const b=S.button(label,()=>{close();Promise.resolve().then(fn).catch(S.error)});b.setAttribute('role','menuitem');menu.append(b)}document.body.append(menu);menu.style.left=Math.max(4,Math.min(event?.clientX||20,innerWidth-menu.offsetWidth-8))+'px';menu.style.top=Math.max(4,Math.min(event?.clientY||80,innerHeight-menu.offsetHeight-8))+'px';document.addEventListener('keydown',key,true);queueMicrotask(()=>document.addEventListener('pointerdown',outside,true));menu.querySelector('button')?.focus();return menu};
 S.context=(node,choices)=>{node.addEventListener('contextmenu',e=>S.menu(e,typeof choices==='function'?choices():choices));let timer=null,point=null,consumed=false;node.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'||e.button!==0)return;point=[e.clientX,e.clientY];timer=setTimeout(()=>{consumed=true;S.menu({clientX:e.clientX,clientY:e.clientY,preventDefault(){},stopPropagation(){}},typeof choices==='function'?choices():choices)},650)});node.addEventListener('pointermove',e=>{if(point&&Math.hypot(e.clientX-point[0],e.clientY-point[1])>10)clearTimeout(timer)});for(const name of ['pointerup','pointercancel'])node.addEventListener(name,()=>clearTimeout(timer));node.addEventListener('click',e=>{if(consumed){e.preventDefault();e.stopImmediatePropagation();consumed=false}},true);node.addEventListener('keydown',e=>{if(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10')S.menu(e,typeof choices==='function'?choices():choices)})};
 S.form=(heading,fields,initial={},save)=>{openModal('<div id="studioFormHost"></div>');const root=document.getElementById('studioFormHost'),form=S.node('form','studio-form');root.append(S.node('h2','',heading),form);const id='form-'+heading+'-'+(initial.id||'new'),draft=S.readDraft(id),values=draft||initial,inputs={};for(const field of fields){const label=S.node('label','',field.label);let input;if(field.options){input=S.node('select');field.options.forEach(([v,t])=>{const op=S.node('option','',t);op.value=v;input.append(op)})}else input=S.node(field.type==='textarea'?'textarea':'input');if(input.tagName==='INPUT')input.type=field.type||'text';input.name=field.key;input.value=values[field.key]??field.default??'';if(field.required)input.required=true;if(field.min!==undefined)input.min=field.min;if(field.max!==undefined)input.max=field.max;if(field.step)input.step=field.step;input.maxLength=field.maxLength||10000;label.append(input);form.append(label);inputs[field.key]=input}const status=S.node('p','studio-status');status.setAttribute('role','status');const button=S.node('button','primary','Enregistrer');button.type='submit';form.append(status,button,S.button('Fermer',closeModal));const read=()=>Object.fromEntries(Object.entries(inputs).map(([k,n])=>[k,n.value]));form.oninput=()=>S.draft(id,read());form.onsubmit=async e=>{e.preventDefault();button.disabled=true;S.draft(id,read());try{await save(read());S.clearDraft(id);closeModal()}catch(error){status.textContent=error.message}finally{button.disabled=false}};if(draft)status.textContent='Brouillon local retrouvé.';return form};
 S.tabs=(root,names,active,choose)=>{const nav=S.node('div','studio-tabs');nav.setAttribute('role','tablist');for(const [id,title] of names){const b=S.button(title,()=>choose(id),active===id?'selected':'');b.setAttribute('role','tab');b.setAttribute('aria-selected',String(active===id));nav.append(b)}root.append(nav);return nav};
 S.color=v=>/^#[0-9a-f]{6}$/i.test(v||'')?v:'#91a98d';
 S.refresh().catch(S.error);
})();
